    """Return (True, msg) if the file exists and is non-empty."""
    if not os.path.isfile(path):
        return False, f"File missing (cannot check emptiness): {path}"
    size = os.path.getsize(path)
    if size == 0:
        return False, f"File is empty: {path}"
    return True, f"File is non-empty ({size} bytes): {path}"


