        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            header = next(reader, None)
            if header is None:
                return False, f"File has no header row: {path}"
            row_count = sum(1 for _ in reader)
        if row_count == 0:
            return False, f"File has no data rows: {path}"
        return True, f"File has {row_count} data row(s): {path}"
    except Exception as exc:
        return False, f"Error reading rows: {exc}"


