    ("t05_file_not_empty", check_file_not_empty, "outputs/t05_clean_stops.csv"),
    ("t05_has_rows", check_csv_has_rows, "outputs/t05_clean_stops.csv"),
    (
        "t05_expected_columns",
        check_csv_columns,
        "outputs/t05_clean_stops.csv",
        ["stop_id", "stop_name", "stop_lat", "stop_lon"],
