    ("t05_latitude_range", check_latitude_range, "outputs/t05_clean_stops.csv"),
    ("t05_longitude_range", check_longitude_range, "outputs/t05_clean_stops.csv"),
    ("t05_stop_count", check_stop_count, "outputs/t05_clean_stops.csv", 1),

    # --- t08_pois_clean.csv ---
    ("t08_file_exists", check_file_exists, "outputs/t08_pois_clean.csv"),
    ("t08_file_not_empty", check_file_not_empty, "outputs/t08_pois_clean.csv"),
    ("t08_has_rows", check_csv_has_rows, "outputs/t08_pois_clean.csv"),
    (
        "t08_expected_columns",
        check_csv_columns,
        "outputs/t08_pois_clean.csv",
        ["qid", "label", "poi_type", "latitude", "longitude", "source"],
    ),
    ("t08_latitude_range", check_latitude_range, "outputs/t08_pois_clean.csv"),
    ("t08_longitude_range", check_longitude_range, "outputs/t08_pois_clean.csv"),
    ("t08_poi_count", check_poi_count, "outputs/t08_pois_clean.csv", 1),

    # --- t10_accessibility_scores.csv ---
    (
        "t10_file_exists",
        check_file_exists,
        "outputs/t10_accessibility_scores.csv",
    ),
    (
        "t10_file_not_empty",
        check_file_not_empty,
        "outputs/t10_accessibility_scores.csv",
    ),
    (
        "t10_has_rows",
        check_csv_has_rows,
        "outputs/t10_accessibility_scores.csv",
    ),
    (
        "t10_expected_columns",
        check_csv_columns,
        "outputs/t10_accessibility_scores.csv",
        [
            "qid",
            "label",
            "poi_type",
            "distance_m",
            "n_departures",
            "n_routes",
            "accessibility_score",
        ],
    ),
    (
        "t10_distance_positive",
        check_distance_positive,
        "outputs/t10_accessibility_scores.csv",
    ),
    (
        "t10_score_range",
        check_accessibility_score_range,
        "outputs/t10_accessibility_scores.csv",
    ),
    (
        "t10_score_count",
        check_accessibility_count,
        "outputs/t10_accessibility_scores.csv",
        1,
    ),

    # --- t13_city_clusters.csv ---
    (
        "t13_file_exists",
        check_file_exists,
        "outputs/t13_city_clusters.csv",
    ),
    (
        "t13_file_not_empty",
        check_file_not_empty,
        "outputs/t13_city_clusters.csv",
    ),
    (
        "t13_has_rows",
        check_csv_has_rows,
        "outputs/t13_city_clusters.csv",
    ),
    (
        "t13_expected_columns",
        check_csv_columns,
        "outputs/t13_city_clusters.csv",
        ["city_id", "city_name", "year", "cluster_id"],
    ),
    (
        "t13_cluster_id_valid",
        check_cluster_id_valid,
        "outputs/t13_city_clusters.csv",
    ),
    (
        "t13_cluster_count",
        check_cluster_count,
        "outputs/t13_city_clusters.csv",
        1,
    ),
]


# ---------------------------------------------------------------------------
# Run validation
# ---------------------------------------------------------------------------


def run_validation():
    results = []
    for entry in ALL_CHECKS:
        check_name = entry[0]
        check_fn = entry[1]
        # Remaining entries are positional args for the check function
        args = entry[2:]
        try:
            passed, message = check_fn(*args)
        except Exception as exc:
            passed = False
            message = f"Check raised exception: {exc}"
        results.append(
            {
                "check_name": check_name,
                "passed": passed,
                "message": message,
            }
        )

    output_path = os.path.join(OUTPUT_DIR, "t14_validation_summary.json")
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as fh:
        json.dump(results, fh, indent=2, ensure_ascii=False)

    # Print summary to stdout
    total = len(results)
    passed_count = sum(1 for r in results if r["passed"])
    failed_count = total - passed_count
    print(f"Validation complete: {total} checks, {passed_count} passed, {failed_count} failed.")
    for r in results:
        status = "PASS" if r["passed"] else "FAIL"
        print(f"  [{status}] {r['check_name']}: {r['message']}")

    return results


if __name__ == "__main__":
    run_validation()
"}

